func arraysByteCopyRangeFullProject(t *testing.T, name string) {
	t.Helper()
	var projects []struct {
		Name  string
		Entry string
		Files map[string]string
	}
	var recorded []struct {
		Program string
		Seed    int
		Repeat  int
		Stdout  string
		Stderr  string
	}
	if err := json.Unmarshal([]byte(arraysByteCopyRangeProjectsJSON), &projects); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal([]byte(arraysByteCopyRangeObservationsJSON), &recorded); err != nil {
		t.Fatal(err)
	}
	for _, p := range projects {
		if p.Name == name {
			var observations []campaignCompilerProjectObservation
			for _, r := range recorded {
				if r.Program == name {
					observations = append(observations, campaignCompilerProjectObservation{name: fmt.Sprintf("seed-%d-repeat-%d", r.Seed, r.Repeat), args: []string{strconv.Itoa(r.Seed)}, stdout: r.Stdout, stderr: r.Stderr})
				}
			}
			if len(observations) != 9 {
				t.Fatal("nine actual-JDK observations required")
			}
			runCampaignCompilerStrictProjectObservations(t, p.Files, p.Entry, observations)
			return
		}
	}
	t.Fatal("unknown full program")
}
func TestArraysByteCopyRangeStatefulJDK21(t *testing.T) {
	arraysByteCopyRangeFullProject(t, "stateful")
}
func TestArraysByteCopyRangeImportsJDK21(t *testing.T) { arraysByteCopyRangeFullProject(t, "imports") }
func TestArraysByteCopyRangeSourceGuardsJDK21(t *testing.T) {
	arraysByteCopyRangeFullProject(t, "sourceGuards")
}
func TestArraysByteCopyRangeConversionJDK21(t *testing.T) {
	arraysByteCopyRangeFullProject(t, "conversion")
}

func TestArraysByteCopyRangeSelectionRegistryAgreement(t *testing.T) {
	tests := []struct {
		name, source string
		selected     bool
	}{
		{"explicit", `import java.util.Arrays;class Main{static byte[] run(byte[] a){return Arrays.copyOfRange(a,0,1);}}`, true},
		{"qualified", `class Main{static byte[] run(byte[] a){return java.util.Arrays.copyOfRange(a,0,1);}}`, true},
		{"wildcard", `import java.util.*;class Main{static byte[] run(byte[] a){return Arrays.copyOfRange(a,0,1);}}`, true},
		{"static", `import static java.util.Arrays.copyOfRange;class Main{static byte[] run(byte[] a){return copyOfRange(a,0,1);}}`, true},
		{"typednull", `import java.util.Arrays;class Main{static byte[] run(){return Arrays.copyOfRange((byte[])null,0,1);}}`, true},
		{"nullarrayvariable", `import java.util.Arrays;class Main{static byte[] run(byte[] a){return Arrays.copyOfRange(a,0,1);}}`, true},
		{"boxed", `import java.util.Arrays;class Main{static byte[] run(byte[] a,Integer i){return Arrays.copyOfRange(a,i,1);}}`, true},
		{"primitivewidening", `import java.util.Arrays;class Main{static byte[] run(byte[] a,byte f,char t){return Arrays.copyOfRange(a,f,t);}}`, true},
		{"noimport", `class Main{static byte[] run(byte[] a){return Arrays.copyOfRange(a,0,1);}}`, false},
		{"foreignimport", `import foreign.Arrays;class Main{static byte[] run(byte[] a){return Arrays.copyOfRange(a,0,1);}}`, false},
		{"foreignqualified", `class Main{static byte[] run(byte[] a){return foreign.Arrays.copyOfRange(a,0,1);}}`, false},
		{"bare-null-ambiguous", `import java.util.Arrays;class Main{static byte[] run(){return Arrays.copyOfRange(null,0,1);}}`, false},
		{"char-overload", `import java.util.Arrays;class Main{static char[] run(char[] a){return Arrays.copyOfRange(a,0,1);}}`, false},
		{"reference-overload", `import java.util.Arrays;class Main{static Object[] run(Object[] a){return Arrays.copyOfRange(a,0,1);}}`, false},
		{"nestedarray-overload", `import java.util.Arrays;class Main{static byte[][] run(byte[][] a){return Arrays.copyOfRange(a,0,1);}}`, false},
		{"long-inapplicable", `import java.util.Arrays;class Main{static byte[] run(byte[] a,long i){return Arrays.copyOfRange(a,i,1);}}`, false},
		{"double-inapplicable", `import java.util.Arrays;class Main{static byte[] run(byte[] a,double i){return Arrays.copyOfRange(a,0,i);}}`, false},
		{"wrongarity", `import java.util.Arrays;class Main{static byte[] run(byte[] a){return Arrays.copyOfRange(a,0);}}`, false},
		{"source", `class Main{static class Arrays{static byte[] copyOfRange(byte[] a,int f,int t){return a;}}static byte[] run(byte[] a){return Arrays.copyOfRange(a,0,1);}}`, false},
		{"value", `class Main{static class Peer{byte[] copyOfRange(byte[] a,int f,int t){return a;}}static byte[] run(byte[] a,Peer Arrays){return Arrays.copyOfRange(a,0,1);}}`, false},
		{"typebinder", `class Main<Arrays>{static byte[] run(byte[] a){return java.util.Arrays.copyOfRange(a,0,1);}}`, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			h := setupParseHelper(t, tt.source)
			ctx := h.Ctx.Clone()
			ctx.className = ctx.currentClass.Class.Name
			ctx.localScope = ctx.currentClass.FindMethod().ByOriginalName("run")[0]
			invocation := findNode(ctx.localScope.DeclarationNode, "method_invocation")
			if got := arraysByteCopyRangeSelected(invocation, ctx, h.File.Source); got != tt.selected {
				t.Fatalf("selection=%v want%v", got, tt.selected)
			}
			expected := staticIntrinsicExpectedArguments[intrinsicKey{"Arrays", "copyOfRange"}](invocation, ctx, h.File.Source)
			result, known := inferStaticIntrinsicResultType(invocation, "Arrays", "copyOfRange", ctx, h.File.Source)
			args := []ast.Expr{ast.NewIdent("stagedOriginal"), ast.NewIdent("stagedFrom"), ast.NewIdent("stagedTo")}
			lowered := lowerArraysByteCopyRange(invocation, args, ctx, h.File.Source)
			if tt.selected {
				if !slices.Equal(expected, []string{"byte[]", "int", "int"}) || !known || result != "byte[]" {
					t.Fatalf("registry disagreement: expected=%v result=%q/%v", expected, result, known)
				}
				call, ok := lowered.(*ast.CallExpr)
				if !ok || len(call.Args) != 3 {
					t.Fatal("runtime call missing")
				}
				for i := range args {
					if call.Args[i] != args[i] {
						t.Fatal("staged argument replaced or reparsed")
					}
				}
			} else if expected != nil || known || lowered != nil {
				t.Fatalf("unselected declaration acquired intrinsic ABI: expected=%v result=%q/%v expression=%T", expected, result, known, lowered)
			}
		})
	}
	if arraysByteCopyRangeSelected(nil, Ctx{}, nil) {
		t.Fatal("nil invocation selected")
	}
}
